# Constants and Enums
HTTP_REQUEST = 0
HTTP_RESPONSE = 1
HTTP_BOTH = 2

F_CHUNKED = 1
F_CONNECTION_KEEP_ALIVE = 2
F_CONNECTION_CLOSE = 4
F_CONNECTION_UPGRADE = 8
F_TRAILING = 16
F_UPGRADE = 32
F_SKIPBODY = 64
F_CONTENTLENGTH = 128

class http_parser:
    def __init__(self, *args, **kwargs):
        # Allow robust initialization from dict, object, or positional arguments
        if args and isinstance(args[0], dict):
            for k, v in args[0].items():
                setattr(self, k, v)
        for k, v in kwargs.items():
            setattr(self, k, v)

        # Default struct fields if not provided
        if not hasattr(self, 'type'):
            self.type = HTTP_REQUEST
        if not hasattr(self, 'flags'):
            self.flags = 0
        if not hasattr(self, 'state'):
            self.state = 0
        if not hasattr(self, 'header_state'):
            self.header_state = 0
        if not hasattr(self, 'index'):
            self.index = 0
        if not hasattr(self, 'uses_transfer_encoding'):
            self.uses_transfer_encoding = 0
        if not hasattr(self, 'allow_chunked_length'):
            self.allow_chunked_length = 0
        if not hasattr(self, 'lenient_http_headers'):
            self.lenient_http_headers = 0

    def get(self, key, default=None):
        return getattr(self, key, default)


def http_should_keep_alive(parser: http_parser) -> int:
    """
    Determines if the connection should be kept alive after the current message.
    """
    if parser is None:
        return 0

    flags = getattr(parser, 'flags', 0)

    # If F_CONNECTION_CLOSE is set, do not keep alive
    if flags & F_CONNECTION_CLOSE:
        return 0

    # If F_CONNECTION_KEEP_ALIVE is set, keep alive
    if flags & F_CONNECTION_KEEP_ALIVE:
        return 1

    # HTTP/1.1 or HTTP/1.0 persistent connection rules can be evaluated via flags or parser state if implemented,
    # but strictly based on the technical specification flags:
    return 0
